  auto _CREATION_DATE = _o->CREATION_DATE.empty() ? 0 : _fbb.CreateString(_o->CREATION_DATE);
  auto _ORIGINATOR = _o->ORIGINATOR.empty() ? 0 : _fbb.CreateString(_o->ORIGINATOR);
